import json
import os
import sys
import urllib.request


def send_rpc(data_dir, payload):
    hub_json_path = os.path.join(data_dir, "runtime", "hub.json")
    with open(hub_json_path, "r", encoding="utf-8") as handle:
        hub = json.load(handle)
    with open(hub["tokenFile"], "r", encoding="utf-8") as handle:
        token = handle.read().strip()

    body = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    request = urllib.request.Request(
        f"{hub['httpBaseUrl']}/rpc",
        data=body,
        headers={
            "Content-Type": "application/json",
            "Authorization": f"Bearer {token}",
            "X-DevHub-Protocol": "1",
            "X-DevHub-ClientId": "ConformanceLaunchMismatchProcess",
            "X-DevHub-ClientSessionId": "00000000-0000-0000-0000-000000000130"
        },
        method="POST"
    )
    with urllib.request.urlopen(request, timeout=10) as response:
        return json.loads(response.read().decode("utf-8"))


def main():
    data_dir, app_id, wrong_scope, instance_id = sys.argv[1:5]
    launch_id = os.environ.get("DEVHUB_LAUNCH_ID")
    result_path = os.path.join(data_dir, "register-result.json")

    if not launch_id:
        with open(result_path, "w", encoding="utf-8") as handle:
            json.dump({"scriptError": "missing launch id"}, handle, ensure_ascii=False)
        return 2

    register_payload = {
        "jsonrpc": "2.0",
        "id": "apps-launch-scope-mismatch-register",
        "method": "hub.apps.registerInstance",
        "params": {
            "password": "bound-password",
            "launchId": launch_id,
            "instance": {
                "instanceId": instance_id,
                "appId": app_id,
                "scope": wrong_scope,
                "pid": os.getpid(),
                "invoke": {
                    "poll": True,
                    "respond": True
                }
            }
        }
    }

    response = send_rpc(data_dir, register_payload)
    with open(result_path, "w", encoding="utf-8") as handle:
        json.dump(response, handle, ensure_ascii=False)

    if isinstance(response.get("result"), dict) and response["result"].get("ok") is True:
        instance_session_token = response["result"].get("instanceSessionToken")
        if isinstance(instance_session_token, str) and instance_session_token:
            unregister_payload = {
                "jsonrpc": "2.0",
                "id": "apps-launch-scope-mismatch-unregister",
                "method": "hub.apps.unregisterInstance",
                "params": {
                    "instanceId": instance_id,
                    "instanceSessionToken": instance_session_token
                }
            }
            send_rpc(data_dir, unregister_payload)

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
